from typing import Protocol, runtime_checkable


@runtime_checkable
class Renderer(Protocol):
    def render(self, data: list[dict]) -> str:
        ...


class CSVRenderer:
    def render(self, data: list[dict]) -> str:
        lines = [','.join(data[0].keys())]
        lines.extend(','.join(str(v) for v in row.values()) for row in data)
        return '\n'.join(lines)


class JSONRenderer:
    def render(self, data: list[dict]) -> str:
        import json
        return json.dumps(data, indent=2)


class HTMLRenderer:
    def render(self, data: list[dict]) -> str:
        headers = ''.join(f'<th>{k}</th>' for k in data[0].keys())
        rows = ''.join(
            '<tr>' + ''.join(f'<td>{v}</td>' for v in row.values()) + '</tr>'
            for row in data
        )
        return (
            f'<table><thead><tr>{headers}</tr></thead>'
            f'<tbody>{rows}</tbody></table>'
        )


FORMAT_REGISTRY: dict[str, Renderer] = {
    'csv': CSVRenderer(),
    'json': JSONRenderer(),
    'html': HTMLRenderer(),
}


class ReportGenerator:
    def generate(self, data: list[dict], format: str) -> str:
        if format not in FORMAT_REGISTRY:
            raise ValueError(f'Unknown format: {format}')
        return FORMAT_REGISTRY[format].render(data)
